    (hq : q ∈ Finset.Icc 1 (blockLen k)) (hq' : q' ∈ Finset.Icc 1 (blockLen k'))
    (hne : (k, q) ≠ (k', q')) : inner ℂ (aLp k q) (aLp k' q') = 0
